// A synthetic frame so the example runs without a camera: a pale 480x312
// label tilted 4 degrees on a dark 800x600 tray, one channel, with a few
// printed bars. Replace this node with your camera or file-in node.
const width = 800;
const height = 600;
const cx = 400;
const cy = 300;
const labelW = 480;
const labelH = 312;
const angleDeg = 4;
const data = Buffer.alloc(width * height, 60);
const ca = Math.cos((angleDeg * Math.PI) / 180);
const sa = Math.sin((angleDeg * Math.PI) / 180);
const bars = [0.15, 0.3, 0.45, 0.6, 0.75].map((f) => (f - 0.5) * labelH);
for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
        const u = (x - cx) * ca + (y - cy) * sa;
        const v = -(x - cx) * sa + (y - cy) * ca;
        if (Math.abs(u) > labelW / 2 || Math.abs(v) > labelH / 2) continue;
        let value = 236;
        for (const bar of bars) {
            if (Math.abs(u) < labelW * 0.35 && Math.abs(v - bar) < labelH * 0.03) {
                value = 30;
                break;
            }
        }
        data[y * width + x] = value;
    }
}
msg.payload = { data, width, height, channels: 1 };
return msg;
